// Pairs each Bitly response back to its tracked link by item index (robust
// against response reordering), and always emits one row per tracked link --
// even on failure -- so the main report shows N/A instead of silently
// dropping a platform from the Link performance table.

const responses = $input.all();

return responses.map((item, index) => {
  const target = $('Tracked links').itemMatching(index).json;
  const result = item.json;
  const body = result && result.body;
  const statusCode = result && result.statusCode;

  const ok =
    typeof statusCode === 'number' &&
    statusCode >= 200 &&
    statusCode < 300 &&
    body &&
    typeof body.total_clicks === 'number';

  return {
    json: {
      kind: 'link',
      url: target.url,
      clicks: ok ? body.total_clicks : null,
      source: ok ? 'bitly' : '',
    },
  };
});
